//
//         });
//
//       return 0;
//     }
//

#pragma once

#include <type_traits>
#include <functional>
#include <stdexcept>
#include <optional>
#include <cstdint>
#include <cstring>
#include <fstream>
#include <cassert>
#include <memory>
#include <string>
#include <vector>
#include <span>
#include <map>
#include <bit>

#if __cpp_lib_byteswap >= 201806L
# include <bit> // C++23 byteswap
#else
# include <algorithm>
namespace std {
  template <typename T>
  T byteswap(T value) {
    static_assert(std::is_trivially_copyable_v<T>, "Type must be trivially copyable");
    T result;
    std::reverse_copy(reinterpret_cast<const char*>(&value),
                      reinterpret_cast<const char*>(&value) + sizeof(T),
                      reinterpret_cast<char*>(&result));
    return result;
  }
}
